apiVersion: admissionregistration.k8s.io/v1
kind: MutatingAdmissionPolicy
metadata:
  name: "propagate-part-of-label"
spec:
  failurePolicy: Fail
  reinvocationPolicy: Never
  matchConstraints:
    resourceRules:
    - apiGroups:   ["apps"]
      apiVersions: ["v1"]
      operations:  ["CREATE", "UPDATE"]
      resources:   ["deployments"]
  mutations:
  # Mutation 1: stamp a recommended "part-of" label on the Deployment.
  - patchType: ApplyConfiguration
    applyConfiguration:
      expression: >
        Object{
          metadata: Object.metadata{
            labels: {"app.kubernetes.io/part-of": "billing-system"}
          }
        }
  # Mutation 2: copy that label down onto the pod template. The `object`
  # binding here already reflects mutation 1 -- mutations run in order,
  # each one seeing the result of the previous.
  - patchType: ApplyConfiguration
    applyConfiguration:
      expression: >
        Object{
          spec: Object.spec{
            template: Object.spec.template{
              metadata: Object.spec.template.metadata{
                labels: {
                  "app.kubernetes.io/part-of": object.metadata.labels["app.kubernetes.io/part-of"]
                }
              }
            }
          }
        }
